"stepMusic"]=[[jiaobu]],["up"]=[[fb17_18]]},["fb17_08"]={["dsc"]=[[一条曲曲折折用鹅卵石铺成的小径，路两旁绿柳成荫，一处处山石花木点缀在其中。你走在石地上，啪嗒啪嗒的发出清脆的响声，东面是小径的延伸。]],["id"]=[[fb17_08]],["item1"]=[[fb17item9]],["item2"]=[[fb17item9]],["left"]=[[fb17_07]],["name"]=[[小径]],["permission"]=1,["right"]=[[fb17_09]],["stepMusic"]=[[jiaobu]]},["fb17_09"]={["dsc"]=[[一条曲曲折折用鹅卵石铺成的小径，路两旁绿柳成荫，一处处山石花木点缀在其中。你走在石地上，啪嗒啪嗒的发出清脆的响声，东面是一座小坟。]],["id"]=[[fb17_09]],["item1"]=[[fb17item9]],["item2"]=[[fb17item9]],["left"]=[[fb17_08]],["name"]=[[小径]],["permission"]=1,["right"]=[[fb17_10]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_11]]},["fb17_10"]={["dsc"]=[[这里是燕氏的坟场，燕氏一脉死后都要被安葬这里，世世代代，无一例外。每到清明时分，燕氏后裔都要在这里祭祖。]],["id"]=[[fb17_10]],["item1"]=[[fb17item5]],["item2"]=[[fb17item100]],["left"]=[[fb17_09]],["name"]=[[坟墓]],["permission"]=2,["role1"]=[[fb17r10_2]],["stepMusic"]=[[jiaobu]]},["fb17_11"]={["down"]=[[fb17_09]],["dsc"]=[[这里是小径旁树丛中央的一个大平台。平台呈圆形，地上按二十八宿的方位排布着一些木桩，其中一根最北边的木桩显得格外的粗壮。平台四周树丛掩映，阳光透过树叶的缝隙在平台上留下了班驳的树影。]],["id"]=[[fb17_11]],["item1"]=[[bfitem2]],["name"]=[[观星台]],["permission"]=1,["role1"]=[[fb17r11_1]],["stepMusic"]=[[jiaobu]]},["fb17_12"]={["down"]=[[fb17_01]],["dsc"]=[[这里是一道圆形小门，小门的南面是一条长廊，长廊里面人来人往，所有的人都在忙着自己的事情。]],["id"]=[[fb17_12]],["item1"]=[[fb17item24]],["item2"]=[[bfitem7]],["name"]=[[小门]],["permission"]=1,["role1"]=[[fb17r12_1]],["role2"]=[[fb17r12_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_19]]},["fb17_13"]={["dsc"]=[[这是一条长廊，上面画着江南秀美的工笔画。绿色的柱子朱红色的琉璃瓦，使得你不由得对江南艺术工匠的创造惊叹不已。在长廊里面，丫鬟、家丁们走来走去，都忙着自己的事情，不敢有一点怠慢。]],["id"]=[[fb17_13]],["name"]=[[长廊]],["permission"]=1,["right"]=[[fb17_14]],["role1"]=[[fb17r13_1]],["role2"]=[[fb17r13_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_20]]},["fb17_14"]={["down"]=[[fb17_03]],["dsc"]=[[这里是修身养性的好场所，这里静悄悄的，没有主人的吩咐，谁也不能够随便出入这里，在墙上挂着一幅图。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb17_14]],["item1"]=[[lylitem1]],["left"]=[[fb17_13]],["name"]=[[静音阁]],["permission"]=1,["right"]=[[fb17_15]],["role1"]=[[fb17r14_100]],["stepMusic"]=[[jiaobu]]},["fb17_15"]={["dsc"]=[[这里是镜花坞的内堂，里面是平时燕氏家眷呆的地方，丫鬟和婢女们在这里伺候着燕氏一脉。墙面上挂着一幅五寿图，房梁是用上好的楠木做的。屋子中间放着一张八仙桌，桌子上摆着水蜜桃和荔枝。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb17_15]],["item1"]=[[fb17item114]],["left"]=[[fb17_14]],["name"]=[[内堂]],["permission"]=1,["right"]=[[fb17_16]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_22]]},["fb17_16"]={["down"]=[[fb17_05]],["dsc"]=[[赏月斋是为燕氏一脉每到中秋之夜而建造的。里面富丽堂皇，瓜果应有尽有，旁边有丫鬟伺候着，每到赏月之时，一家老小都在这里赏月，在赏月的同时，也念念不忘复兴大燕的使命。西面是内堂，东面和南面是一条长廊。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb17_16]],["left"]=[[fb17_15]],["name"]=[[赏月斋]],["permission"]=1,["right"]=[[fb17_17]],["role1"]=[[fb17r16_1]],["stepMusic"]=[[jiaobu]]},["fb17_17"]={["dsc"]=[[这是一条长廊，上面画着江南秀美的工笔画。绿色的柱子朱红色的琉璃瓦，使得你不由得对江南艺术工匠的创造惊叹不已。在长廊里面，丫鬟、家丁们走来走去，都忙着自己的事情，不敢有一点怠慢。]],["id"]=[[fb17_17]],["left"]=[[fb17_16]],["name"]=[[长廊]],["permission"]=1,["role1"]=[[fb17r17_1]],["role2"]=[[fb17r17_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_24]]},["fb17_18"]={["down"]=[[fb17_07]],["dsc"]=[[这里是一道圆形小门，小门的南面是一条长廊，长廊里面人来人往，所有的人都在忙着自己的事情。]],["id"]=[[fb17_18]],["name"]=[[小门]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb17_25]]},["fb17_19"]={["down"]=[[fb17_12]],["dsc"]=[[这是一条长廊，上面画着江南秀美的工笔画。绿色的柱子朱红色的琉璃瓦，使得你不由得对江南艺术工匠的创造惊叹不已。在长廊里面，丫鬟、家丁们走来走去，都忙着自己的事情，不敢有一点怠慢。]],["id"]=[[fb17_19]],["name"]=[[长廊]],["permission"]=1,["right"]=[[fb17_20]],["role1"]=[[fb17r19_1]],["role2"]=[[fb17r19_2]],["stepMusic"]=[[jiaobu]]},["fb17_20"]={["down"]=[[fb17_13]],["dsc"]=[[这是一条长廊，上面画着江南秀美的工笔画。绿色的柱子朱红色的琉璃瓦，使得你不由得对江南艺术工匠的创造惊叹不已。在长廊里面，丫鬟、家丁们走来走去，都忙着自己的事情，不敢有一点怠慢。]],["id"]=[[fb17_20]],["left"]=[[fb17_19]],["name"]=[[长廊]],["permission"]=1,["right"]=[[fb17_21]],["role1"]=[[fb17r20_1]],["role2"]=[[fb17r20_2]],["role3"]=[[fb17r20_100]],["role4"]=[[fb17r20_101]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_26]]},["fb17_21"]={["dsc"]=[[这是一间厢房，里面摆设简单，只有一张床，一张书桌和一把椅子。]],["id"]=[[fb17_21]],["item1"]=[[fb17item14]],["item2"]=[[fb17item15]],["item3"]=[[fb17item111]],["left"]=[[fb17_20]],["name"]=[[厢房]],["permission"]=1,["right"]=[[fb17_22]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_27]]},["fb17_22"]={["down"]=[[fb17_15]],["dsc"]=[[这里是燕氏商议事情的地方，不是燕氏弟子最好不要到这里来。在后堂正中摆放着一个香案，上面摆放着一个灵位牌子，在正中墙上挂着一幅百鸟朝凤图，边墙上挂着一口宝剑。东西两面各是一间厢房，南面是内堂。]],["id"]=[[fb17_22]],["left"]=[[fb17_21]],["name"]=[[后厅]],["permission"]=1,["right"]=[[fb17_23]],["role1"]=[[fb17r22_100]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_28]]},["fb17_23"]={["dsc"]=[[这是一间厢房，里面摆设简单，只有一张床，一张书桌和一把椅子。]],["id"]=[[fb17_23]],["item1"]=[[fb17item14]],["item2"]=[[fb17item15]],["left"]=[[fb17_22]],["name"]=[[厢房]],["permission"]=1,["right"]=[[fb17_24]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_29]]},["fb17_24"]={["down"]=[[fb17_17]],["dsc"]=[[这是一条长廊，上面画着江南秀美的工笔画。绿色的柱子朱红色的琉璃瓦，使得你不由得对江南艺术工匠的创造惊叹不已。在长廊里面，丫鬟、家丁们走来走去，都忙着自己的事情，不敢有一点怠慢。]],["id"]=[[fb17_24]],["left"]=[[fb17_23]],["name"]=[[长廊]],["permission"]=1,["right"]=[[fb17_25]],["role1"]=[[fb17r24_1]],["role2"]=[[fb17r24_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_30]]},["fb17_25"]={["down"]=[[fb17_18]],["dsc"]=[[这是一条长廊，上面画着江南秀美的工笔画。绿色的柱子朱红色的琉璃瓦，使得你不由得对江南艺术工匠的创造惊叹不已。在长廊里面，丫鬟、家丁们走来走去，都忙着自己的事情，不敢有一点怠慢。]],["id"]=[[fb17_25]],["left"]=[[fb17_24]],["name"]=[[长廊]],["permission"]=2,["right"]=[[fb17_98]],["role1"]=[[fb17r25_1]],["role2"]=[[fb17r25_2]],["stepMusic"]=[[jiaobu]]},["fb17_26"]={["down"]=[[fb17_20]],["dsc"]=[[这是一条长廊，上面画着江南秀美的工笔画。绿色的柱子朱红色的琉璃瓦，使得你不由得对江南艺术工匠的创造惊叹不已。在长廊里面，丫鬟、家丁们走来走去，都忙着自己的事情，不敢有一点怠慢。]],["id"]=[[fb17_26]],["name"]=[[长廊]],["permission"]=2,["right"]=[[fb17_27]],["role1"]=[[fb17r26_1]],["role2"]=[[fb17r26_2]],["stepMusic"]=[[jiaobu]]},["fb17_27"]={["down"]=[[fb17_21]],["dsc"]=[[这是大家平时休闲起居的地方，里面放着一具古筝，一张棋桌，上面的棋错综复杂，令人百思不得其解。局室的东面是大厅，西面是一条长廊，南面是一间厢房。]],["id"]=[[fb17_27]],["item1"]=[[fb17item11]],["item2"]=[[fb17item12]],["left"]=[[fb17_26]],["name"]=[[局室]],["permission"]=2,["right"]=[[fb17_28]],["stepMusic"]=[[jiaobu]]},["fb17_28"]={["down"]=[[fb17_22]],["dsc"]=[[大厅中陈设简朴，无什摆设，正堂上挂着许多人物字画，都是燕氏祖先的遗迹，用来表示对先人的尊敬。大厅的东边是书房，西边是局室，南面是后厅。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb17_28]],["left"]=[[fb17_27]],["name"]=[[大厅]],["permission"]=1,["right"]=[[fb17_29]],["role1"]=[[fb17r28_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_32]]},["fb17_29"]={["down"]=[[fb17_23]],["dsc"]=[[这里是镜花坞的书房，天下武功皆荟粹与此，包罗万象，屋子南边是一把坐椅，四周全是一排排高大的书架。好好学习，必可成为一代高手。书房的东面是一条长廊，西面是大厅，南面是一间厢房。]],["id"]=[[fb17_29]],["item1"]=[[fb17item13]],["item2"]=[[fb17item14]],["item3"]=[[fb17item15]],["item4"]=[[bfitem1]],["left"]=[[fb17_28]],["name"]=[[书房]],["permission"]=2,["right"]=[[fb17_30]],["role1"]=[[fb17r29_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_33]]},["fb17_30"]={["down"]=[[fb17_24]],["dsc"]=[[这是一条长廊，上面画着江南秀美的工笔画。绿色的柱子朱红色的琉璃瓦，使得你不由得对江南艺术工匠的创造惊叹不已。在长廊里面，丫鬟、家丁们走来走去，都忙着自己的事情，不敢有一点怠慢。]],["id"]=[[fb17_30]],["left"]=[[fb17_29]],["name"]=[[长廊]],["permission"]=2,["right"]=[[fb17_31]],["role1"]=[[fb17r30_1]],["role2"]=[[fb17r30_2]],["stepMusic"]=[[jiaobu]]},["fb17_31"]={["dsc"]=[[这是一间小厨房，虽然不大，但是锅碗瓢盆，油盐酱醋，到很齐全。灶台上堆满了新鲜瓜果蔬菜，活鱼活虾，不仅不脏不乱，还十分干净整齐。]],["id"]=[[fb17_31]],["item1"]=[[fb17item101]],["item2"]=[[bfitem4]],["left"]=[[fb17_30]],["name"]=[[饭厅]],["permission"]=2,["role1"]=[[fb17r31_1]],["stepMusic"]=[[jiaobu]]},["fb17_32"]={["down"]=[[fb17_28]],["dsc"]=[[一条曲曲折折用鹅卵石铺成的小径，路两旁绿柳成荫，一处处山石花木点缀在其中。你走在石地上，啪嗒啪嗒的发出清脆的响声，南面是镜花坞的大厅，专门接待来到山庄的各路英雄豪杰。]],["id"]=[[fb17_32]],["name"]=[[小径]],["permission"]=1,["role1"]=[[2019qxcdg1a]],["role2"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_38]]},["fb17_33"]={["down"]=[[fb17_29]],["dsc"]=[[这里是龙城山庄内的书堂，为了让家里的孩子能够得到很好的教育，山庄特意聘请了一位私塾先生来讲课。]],["id"]=[[fb17_33]],["name"]=[[私塾]],["permission"]=2,["role1"]=[[fb17r33_1]],["stepMusic"]=[[jiaobu]]},["fb17_34"]={["dsc"]=[[这是湖中的一个小亭子，从这望去，可以看到整个湖面的景色，令人心旷神怡。亭子壁上刻画着江南水乡的宜人风景，令人产生无限遐想。亭上有一根梁。]],["id"]=[[fb17_34]],["name"]=[[碧水亭]],["permission"]=1,["right"]=[[fb17_35]],["role1"]=[[fb17r34_1]],["role2"]=[[fb17r34_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_90]]},["fb17_35"]={["dsc"]=[[这是通往湖中小亭的木桥，从这望去湖面碧波荡漾，景色宜人。木桥的扶手上雕刻着一尊尊小木头狮子，让人爱不释手。木桥往西面走能够看到一座湖中小亭。]],["id"]=[[fb17_35]],["left"]=[[fb17_34]],["name"]=[[木桥]],["permission"]=1,["right"]=[[fb17_36]],["stepMusic"]=[[jiaobu]]},["fb17_36"]={["down"]=[[fb17_37]],["dsc"]=[[这是水榭的后院，院中假山水石，无一不透出江南别具一格的风格。只见东西各有一道半月型的小门。东边就是举世闻名的镜花坞了。西面是一座通向湖中小岛的木桥，南面是岸边，可以坐船出太湖。]],["id"]=[[fb17_36]],["left"]=[[fb17_35]],["name"]=[[后院]],["permission"]=1,["right"]=[[fb17_38]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_41]]},["fb17_37"]={["dsc"]=[[这里是龙城山庄的家仆和丫鬟出入太湖的水上码头，只见人们来来往往，一个个风尘仆仆。湖面上有几只小舟正在游弋。]],["id"]=[[fb17_37]],["item1"]=[[2020qixihd]],["name"]=[[岸边]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb17_36]]},["fb17_38"]={["down"]=[[fb17_32]],["dsc"]=[[镜花坞是慕容氏世居之地，慕容氏乃夕日大燕国的后裔，后来日见式微，但其弟子却一心一意想光复大燕。其武功见长于以彼之道，还施彼身，委实厉害无比。]],["id"]=[[fb17_38]],["left"]=[[fb17_36]],["name"]=[[镜花坞]],["permission"]=1,["right"]=[[fb17_39]],["stepMusic"]=[[jiaobu]]},["fb17_39"]={["dsc"]=[[这里是练武场，燕氏的弟子、家丁在这里练习武功，在练武场的一角，有一个专门用来练武的木桩，许多弟子都围在这里练功。]],["fightBackground"]=[[擂台]],["id"]=[[fb17_39]],["item1"]=[[fb17item7]],["left"]=[[fb17_38]],["name"]=[[练武场]],["permission"]=2,["role1"]=[[fb17r39_1]],["role2"]=[[fb17r39_2]],["stepMusic"]=[[jiaobu]]},["fb17_40"]={["dsc"]=[[从这里乘船可以到达紫萝山庄，一位上了年纪的老船夫正在岸边休息，你可以呼喊一声，船家就会摆船过来。]],["id"]=[[fb17_40]],["item1"]=[[2019qxhdd1]],["name"]=[[岸边]],["permission"]=1,["right"]=[[fb17_41]],["role1"]=[[fb17r40_1]],["stepMusic"]=[[jiaobu]]},["fb17_41"]={["down"]=[[fb17_36]],["dsc"]=[[这间房舍小巧玲珑，颇为精雅。小舍匾额上写着“镜花水榭”四个大字，笔致颇为潇洒。再往前走，就到了“镜花坞”。南边是水榭的后院。]],["id"]=[[fb17_41]],["item1"]=[[bfitem9]],["left"]=[[fb17_40]],["name"]=[[镜花水榭]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb17_42]]},["fb17_42"]={["down"]=[[fb17_41]],["dsc"]=[[远远看去，只见一个小洲上八九间房间，其中两间是楼房。阁宇中隐约露出一个牌坊「HIY镜花水榭NOR」。]],["fightBackground"]=[[山内]],["id"]=[[fb17_42]],["item1"]=[[fb17item3]],["name"]=[[岸边]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb17_43"]={["dsc"]=[[这是一片荷花塘，这里种满了荷花，粉红的荷花点缀着湖面，十分好看。]],["id"]=[[fb17_43]],["name"]=[[荷花塘中]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb17_44"]={["dsc"]=[[这是紫萝山庄的一个小码头，从这里上船可以到达龙城山庄的领地，武林中的英雄豪杰们都十分仰慕闻名天下的镜花坞，因为那里是无人不知无人不晓的“以彼之道，还施彼身”的发源地，而燕氏皇族一脉一代就是住在那里。]],["id"]=[[fb17_44]],["name"]=[[岸边]],["permission"]=2,["role1"]=[[fb17r44_1]],["role2"]=[[fb17r44_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_45]]},["fb17_45"]={["down"]=[[fb17_44]],["dsc"]=[[一条曲曲折折用鹅卵石铺成的小径，路两旁绿柳成荫，一处处山石花木点缀在其中。你走在石地上，啪嗒啪嗒的发出清脆的响声，北面是小径的延伸，南面就到了岸边。]],["id"]=[[fb17_45]],["name"]=[[小径]],["permission"]=2,["role1"]=[[fb17r45_1]],["role2"]=[[fb17r45_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_46]]},["fb17_46"]={["down"]=[[fb17_45]],["dsc"]=[[一条曲曲折折用鹅卵石铺成的小径，路两旁绿柳成荫，一处处山石花木点缀在其中。你走在石地上，啪嗒啪嗒的发出清脆的响声，南面是小径的延伸。]],["id"]=[[fb17_46]],["name"]=[[小径]],["permission"]=2,["role1"]=[[fb17r46_1]],["role2"]=[[fb17r46_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_53]]},["fb17_47"]={["down"]=[[fb17_51]],["dsc"]=[[你信步观赏，只见花林中除山茶花外更无别样花卉，连最常见的牵牛花，月月红，蔷薇之类也是一朵都无。走出数十丈后，只见山茶品种渐多，偶而也有一两本还算不错，却也栽种不得其法。]],["id"]=[[fb17_47]],["item1"]=[[fb17item10]],["item2"]=[[fb17item10]],["name"]=[[花丛中]],["permission"]=2,["right"]=[[fb17_48]],["stepMusic"]=[[jiaobu]]},["fb17_48"]={["down"]=[[fb17_52]],["dsc"]=[[这是紫萝山庄的一个小码头，旁边是一片茶花丛，茶花多种多样十分美丽。]],["id"]=[[fb17_48]],["item1"]=[[fb17item4]],["item2"]=[[fb17item10]],["left"]=[[fb17_47]],["name"]=[[岸边]],["permission"]=2,["right"]=[[fb17_49]],["stepMusic"]=[[jiaobu]]},["fb17_49"]={["down"]=[[fb17_53]],["dsc"]=[[你信步观赏，只见花林中除山茶花外更无别样花卉，连最常见的牵牛花，月月红，蔷薇之类也是一朵都无。走出数十丈后，只见山茶品种渐多，偶而也有一两本还算不错，却也栽种不得其法。南面就是庄门了。]],["id"]=[[fb17_49]],["item1"]=[[fb17item10]],["item2"]=[[fb17item10]],["left"]=[[fb17_48]],["name"]=[[花丛中]],["permission"]=2,["right"]=[[fb17_50]],["stepMusic"]=[[jiaobu]]},["fb17_50"]={["down"]=[[fb17_54]],["dsc"]=[[你信步观赏，只见花林中除山茶花外更无别样花卉，连最常见的牵牛花，月月红，蔷薇之类也是一朵都无。走出数十丈后，只见山茶品种渐多，偶而也有一两本还算不错，却也栽种不得其法。南面就是前院。]],["id"]=[[fb17_50]],["item1"]=[[fb17item10]],["item2"]=[[fb17item10]],["left"]=[[fb17_49]],["name"]=[[花丛中]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb17_51"]={["dsc"]=[[你信步观赏，只见花林中除山茶花外更无别样花卉，连最常见的牵牛花，月月红，蔷薇之类也是一朵都无。走出数十丈后，只见山茶品种渐多，偶而也有一两本还算不错，却也栽种不得其法。]],["id"]=[[fb17_51]],["item1"]=[[fb17item10]],["item2"]=[[fb17item10]],["item3"]=[[ycitem1]],["name"]=[[花丛中]],["permission"]=2,["right"]=[[fb17_52]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_47]]},["fb17_52"]={["dsc"]=[[你信步观赏，只见花林中除山茶花外更无别样花卉，连最常见的牵牛花，月月红，蔷薇之类也是一朵都无。走出数十丈后，只见山茶品种渐多，偶而也有一两本还算不错，却也栽种不得其法。东面就是庄门了。]],["id"]=[[fb17_52]],["item1"]=[[fb17item10]],["item2"]=[[fb17item10]],["left"]=[[fb17_51]],["name"]=[[花丛中]],["permission"]=2,["right"]=[[fb17_53]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_48]]},["fb17_53"]={["down"]=[[fb17_46]],["dsc"]=[[你转过一丛茂密的花丛，猛然间，只见一座红檐绿瓦，小巧玲珑的庄院在灿澜的花丛中。庄门大匾上赫然写着「HIY紫萝山庄」四个金光闪闪的大字。]],["id"]=[[fb17_53]],["item1"]=[[fb17item8]],["left"]=[[fb17_52]],["name"]=[[庄门]],["permission"]=2,["right"]=[[fb17_54]],["role1"]=[[fb17r53_1]],["role2"]=[[fb17r53_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_49]]},["fb17_54"]={["down"]=[[fb17_64]],["dsc"]=[[这里是紫萝山庄的前院，只见一个个丫环，婢女人来人往穿梭不息，而且个个步法轻灵，显然武功不弱！院子的东面是一个小石桥，南面是一条长廊。往西走就到了庄门。]],["id"]=[[fb17_54]],["item1"]=[[fb17item8]],["left"]=[[fb17_53]],["name"]=[[HIR前院]],["permission"]=2,["right"]=[[fb17_55]],["role1"]=[[fb17r54_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_50]]},["fb17_55"]={["dsc"]=[[这是一座小小的白石拱桥。桥下碧绿的湖水正荡着微波。石桥的东面是一条鹅卵石铺成的小径，西面是紫萝山庄的前院。]],["id"]=[[fb17_55]],["left"]=[[fb17_54]],["name"]=[[石桥]],["permission"]=2,["right"]=[[fb17_56]],["role1"]=[[fb17r55_1]],["role2"]=[[fb17r55_100]],["role3"]=[[fb17r55_101]],["role4"]=[[fb17r55_102]],["stepMusic"]=[[jiaobu]]},["fb17_56"]={["down"]=[[fb17_66]],["dsc"]=[[一条曲曲折折用鹅卵石铺成的小径，路两旁绿柳成荫，一处处山石花木点缀在其中。你走在石地上，啪嗒啪嗒的发出清脆的响声，往北面看去是一片柳树林，南面是一条长廊。东面是小径的延伸。]],["id"]=[[fb17_56]],["left"]=[[fb17_55]],["name"]=[[小径]],["permission"]=2,["right"]=[[fb17_57]],["role1"]=[[fb17r56_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_60]]},["fb17_57"]={["down"]=[[fb17_67]],["dsc"]=[[一条曲曲折折用鹅卵石铺成的小径，路两旁绿柳成荫，一处处山石花木点缀在其中。你走在石地上，啪嗒啪嗒的发出清脆的响声，往北面看去是一片柳树林，南面和东面是小径的延伸。]],["id"]=[[fb17_57]],["left"]=[[fb17_56]],["name"]=[[小径]],["permission"]=2,["right"]=[[fb17_58]],["role1"]=[[fb17r57_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_61]]},["fb17_58"]={["down"]=[[fb17_68]],["dsc"]=[[一条曲曲折折用鹅卵石铺成的小径，路两旁绿柳成荫，一处处山石花木点缀在其中。你走在石地上，啪嗒啪嗒的发出清脆的响声，往北面看去是一片柳树林，东面是一座小水池，南面是一条长廊。]],["id"]=[[fb17_58]],["left"]=[[fb17_57]],["name"]=[[小径]],["permission"]=2,["right"]=[[fb17_59]],["role1"]=[[fb17r58_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_62]]},["fb17_59"]={["dsc"]=[[这是一大水池。一阵微风吹过，水中菏叶随风在水面上漂浮，水面碧波涌起，妙不可言。水池中央有一座假山，其中的石洞是很多的，使人忍不住想探个究竟。]],["id"]=[[fb17_59]],["left"]=[[fb17_58]],["name"]=[[水池]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb17_60"]={["down"]=[[fb17_56]],["dsc"]=[[这是一片碧绿的柳树林，一片碧绿的颜色，柳树看上去枝叶茂盛，树上几只小鸟唧唧喳喳的叫个不停，柳条随着微风轻轻摆动。]],["fightBackground"]=[[森林内]],["id"]=[[fb17_60]],["item1"]=[[fb17item104]],["item2"]=[[fb17item106]],["item3"]=[[fb17item106]],["item4"]=[[fb17item110]],["name"]=[[柳树林]],["permission"]=2,["right"]=[[fb17_61]],["role1"]=[[fb17r60_100]],["stepMusic"]=[[jiaobu]]},["fb17_61"]={["down"]=[[fb17_57]],["dsc"]=[[这是一片碧绿的柳树林，一片碧绿的颜色，柳树看上去枝叶茂盛，树上几只小鸟唧唧喳喳的叫个不停，柳条随着微风轻轻摆动。]],["fightBackground"]=[[森林内]],["id"]=[[fb17_61]],["item1"]=[[fb17item9]],["item2"]=[[fb17item9]],["item3"]=[[fb17item9]],["left"]=[[fb17_60]],["name"]=[[柳树林]],["permission"]=2,["right"]=[[fb17_62]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_63]]},["fb17_62"]={["down"]=[[fb17_58]],["dsc"]=[[这是一片碧绿的柳树林，一片碧绿的颜色，柳树看上去枝叶茂盛，树上几只小鸟唧唧喳喳的叫个不停，柳条随着微风轻轻摆动。]],["fightBackground"]=[[森林内]],["id"]=[[fb17_62]],["item1"]=[[fb17item9]],["item2"]=[[fb17item9]],["item3"]=[[fb17item25]],["left"]=[[fb17_61]],["name"]=[[柳树林]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb17_63"]={["down"]=[[fb17_61]],["dsc"]=[[这是一片碧绿的柳树林，草地中间有两棵大树，看上去枝叶茂盛，树上几只小鸟唧唧喳喳的叫个不停。]],["fightBackground"]=[[森林内]],["id"]=[[fb17_63]],["item1"]=[[fb17item9]],["item2"]=[[fb17item9]],["item3"]=[[fb17item9]],["name"]=[[柳树林]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb17_64"]={["dsc"]=[[这是一条长廊，上面画着江南秀美的工笔画。绿色的柱子朱红色的琉璃瓦，使得你不由得对江南艺术工匠的创造惊叹不已。在长廊里面，丫鬟、家丁们走来走去，都忙着自己的事情，不敢有一点怠慢。东面是长廊的延伸。]],["id"]=[[fb17_64]],["name"]=[[长廊]],["permission"]=2,["right"]=[[fb17_65]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_54]]},["fb17_65"]={["dsc"]=[[这是一条长廊，上面画着江南秀美的工笔画。绿色的柱子朱红色的琉璃瓦，使得你不由得对江南艺术工匠的创造惊叹不已。东面是长廊的延伸。隔着长廊你可以看到北面的小石桥。]],["id"]=[[fb17_65]],["left"]=[[fb17_64]],["name"]=[[长廊]],["permission"]=2,["right"]=[[fb17_66]],["stepMusic"]=[[jiaobu]]},["fb17_66"]={["down"]=[[fb17_72]],["dsc"]=[[这是一条长廊，上面画着江南秀美的工笔画。绿色的柱子朱红色的琉璃瓦，使得你不由得对江南艺术工匠的创造惊叹不已。北面是一条小径，南面是长廊的延伸。]],["id"]=[[fb17_66]],["left"]=[[fb17_65]],["name"]=[[长廊]],["permission"]=2,["right"]=[[fb17_67]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_56]]},["fb17_67"]={["down"]=[[fb17_73]],["dsc"]=[[一条曲曲折折用鹅卵石铺成的小径，路两旁绿柳成荫，一处处山石花木点缀在其中。你走在石地上，啪嗒啪嗒的发出清脆的响声，往北面看去是一片柳树林，南面是后院，北面是一条小径。]],["id"]=[[fb17_67]],["left"]=[[fb17_66]],["name"]=[[小径]],["permission"]=2,["right"]=[[fb17_68]],["role1"]=[[fb17r67_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_57]]},["fb17_68"]={["down"]=[[fb17_74]],["dsc"]=[[这是一条长廊，上面画着江南秀美的工笔画。绿色的柱子朱红色的琉璃瓦，使得你不由得对江南艺术工匠的创造惊叹不已。北面是一条小径，南面和东面是长廊的延伸。]],["id"]=[[fb17_68]],["left"]=[[fb17_67]],["name"]=[[长廊]],["permission"]=2,["right"]=[[fb17_69]],["role1"]=[[fb17r68_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_58]]},["fb17_69"]={["dsc"]=[[这是一条长廊，上面画着江南秀美的工笔画。绿色的柱子朱红色的琉璃瓦，使得你不由得对江南艺术工匠的创造惊叹不已。在长廊里面，丫鬟、家丁们走来走去，都忙着自己的事情，不敢有一点怠慢。东面是一座小亭子。]],["id"]=[[fb17_69]],["left"]=[[fb17_68]],["name"]=[[长廊]],["permission"]=2,["right"]=[[fb17_70]],["role1"]=[[fb17r69_1]],["stepMusic"]=[[jiaobu]]},["fb17_70"]={["dsc"]=[[这是个很小的亭子，但是能够看到几乎全部的景色，远处有一片樱桃园。湖中几条小舟在碧绿的湖面上往来穿梭，湖中有一座木桥通向湖中的亭子。在水池的假山上有一个黑乎乎的洞穴。]],["id"]=[[fb17_70]],["left"]=[[fb17_69]],["name"]=[[亭子]],["permission"]=2,["role1"]=[[fb17r70_1]],["stepMusic"]=[[jiaobu]]},["fb17_71"]={["down"]=[[fb17_77]],["dsc"]=[[这是一条长廊，上面画着江南秀美的工笔画。绿色的柱子朱红色的琉璃瓦，使得你不由得对江南艺术工匠的创造惊叹不已。在长廊里面，丫鬟、家丁们走来走去，都忙着自己的事情，南面是长廊的延伸。]],["id"]=[[fb17_71]],["name"]=[[长廊]],["permission"]=2,["right"]=[[fb17_72]],["stepMusic"]=[[jiaobu]]},["fb17_72"]={["down"]=[[fb17_78]],["dsc"]=[[这是一条长廊，上面画着江南秀美的工笔画。绿色的柱子朱红色的琉璃瓦，使得你不由得对江南艺术工匠的创造惊叹不已。北西两面面是长廊的延伸，东面是后院，南面是一间厢房。]],["id"]=[[fb17_72]],["left"]=[[fb17_71]],["name"]=[[长廊]],["permission"]=2,["right"]=[[fb17_73]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_66]]},["fb17_73"]={["down"]=[[fb17_79]],["dsc"]=[[穿过一个半月形的拱门，你来到一座小楼之前。小楼檐下一块匾额，写着:“云锦楼”三个墨绿毫字，楼下前后左右种的都是茶花。但这些茶花都不过是三四流货色，和这精致的楼阁亭榭相比，未免不衬。左右面是一条长廊，南面是云锦楼。]],["id"]=[[fb17_73]],["left"]=[[fb17_72]],["name"]=[[后院]],["permission"]=2,["right"]=[[fb17_74]],["role1"]=[[fb17r73_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_67]]},["fb17_74"]={["down"]=[[fb17_80]],["dsc"]=[[这是一条长廊，上面画着江南秀美的工笔画。绿色的柱子朱红色的琉璃瓦，使得你不由得对江南艺术工匠的创造惊叹不已。丫鬟、家丁们走来走去，都忙着自己的事情，东面是长廊的延伸，南面是客厅，西面就是后院。]],["id"]=[[fb17_74]],["left"]=[[fb17_73]],["name"]=[[长廊]],["permission"]=2,["right"]=[[fb17_75]],["role1"]=[[fb17r74_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_68]]},["fb17_75"]={["down"]=[[fb17_81]],["dsc"]=[[这是一条长廊，上面画着江南秀美的工笔画。绿色的柱子朱红色的琉璃瓦，使得你不由得对江南艺术工匠的创造惊叹不已。丫鬟、家丁们走来走去，都忙着自己的事情，南面是长廊的延伸。]],["id"]=[[fb17_75]],["left"]=[[fb17_74]],["name"]=[[长廊]],["permission"]=2,["right"]=[[fb17_76]],["stepMusic"]=[[jiaobu]]},["fb17_76"]={["dsc"]=[[这是一间小厨房，虽然不大，但是锅碗瓢盆，油盐酱醋，到很奇全。灶台上堆满了新鲜瓜果蔬菜，活鱼活虾，不仅不脏不乱，还十分干净整齐。]],["id"]=[[fb17_76]],["left"]=[[fb17_75]],["name"]=[[饭厅]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb17_77"]={["down"]=[[fb17_82]],["dsc"]=[[这是一条长廊，上面画着江南秀美的工笔画。绿色的柱子朱红色的琉璃瓦，使得你不由得对江南艺术工匠的创造惊叹不已。丫鬟、家丁们走来走去，都忙着自己的事情，东面是一间厢房，南面是长廊的延伸。]],["id"]=[[fb17_77]],["name"]=[[长廊]],["permission"]=2,["right"]=[[fb17_78]],["role1"]=[[fb17r77_1]],["role2"]=[[fb17r77_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_71]]},["fb17_78"]={["dsc"]=[[这是一间厢房，里面摆设简单，只有一张床，一张书桌和一把椅子。]],["id"]=[[fb17_78]],["item1"]=[[fb17item113]],["left"]=[[fb17_77]],["name"]=[[厢房]],["permission"]=2,["right"]=[[fb17_79]],["role1"]=[[fb17r78_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_72]]},["fb17_79"]={["down"]=[[fb17_84]],["dsc"]=[[云锦楼陈设富丽，一副中堂绘的是孔雀开屏，两边柱子上写了一幅对联。东面是一间客厅，西面是厢房，往北面走是后院，南面是后花园。]],["id"]=[[fb17_79]],["left"]=[[fb17_78]],["name"]=[[云锦楼]],["permission"]=2,["right"]=[[fb17_80]],["role1"]=[[fb17r79_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_73]]},["fb17_80"]={["dsc"]=[[你走进这间小小的厅室，看到里面放着一张紫檀木茶几和几张湘妃竹椅子，紫檀木的茶几上摆放着茶壶和几只白玉杯，专供客人饮用。你忍不住想坐在竹椅上，让疲惫的身心得到充分的休息。]],["id"]=[[fb17_80]],["left"]=[[fb17_79]],["name"]=[[客厅]],["permission"]=2,["right"]=[[fb17_81]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_74]]},["fb17_81"]={["down"]=[[fb17_86]],["dsc"]=[[这是一条长廊，上面画着江南秀美的工笔画。绿色的柱子朱红色的琉璃瓦，使得你不由得对江南艺术工匠的创造惊叹不已。丫鬟、家丁们走来走去，都忙着自己的事情，西面是一间客厅，南面是长廊的延伸。]],["id"]=[[fb17_81]],["left"]=[[fb17_80]],["name"]=[[长廊]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb17_75]]},["fb17_82"]={["dsc"]=[[这是一条长廊，上面画着江南秀美的工笔画。绿色的柱子朱红色的琉璃瓦，使得你不由得对江南艺术工匠的创造惊叹不已。在长廊里面，丫鬟、家丁们走来走去，都忙着自己的事情，东面是花肥房，北面是长廊的延伸。]],["id"]=[[fb17_82]],["name"]=[[长廊]],["permission"]=2,["right"]=[[fb17_83]],["role1"]=[[fb17r82_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_77]]},["fb17_83"]={["dsc"]=[[石屋黑恫恫的，只见一个人被绑在一根铁柱子上，口里塞满了东西，眼泪汪汪的，却说不出话来。再看两旁时，只见一个弓腰曲背的老婆子手里拿着一柄雪亮的长刀，身旁一锅沸水，煮得直冒热气。]],["id"]=[[fb17_83]],["left"]=[[fb17_82]],["name"]=[[花肥房]],["permission"]=2,["right"]=[[fb17_84]],["role1"]=[[fb17r83_1]],["role2"]=[[fb17r83_3]],["stepMusic"]=[[jiaobu]]},["fb17_84"]={["dsc"]=[[后花园和庄中其它地方一样种满了山茶花，参杂在假山巨石，绿竹小溪中，此所谓:“千呼万唤始出来，犹抱琵琶半遮面”更增姿媚。抬头望去，只见藏书阁的窗户半开着，一根古藤蜒伸在墙上。一股清泉从假山上涌出，尝一口沁人心脾。]],["id"]=[[fb17_84]],["item1"]=[[fb17item6]],["left"]=[[fb17_83]],["name"]=[[后花园]],["permission"]=2,["right"]=[[fb17_85]],["stepMusic"]=[[jiaobu]],["up"]=[[fb17_79]]},["fb17_85"]={["dsc"]=[[这里是紫萝山庄的杂货室，里面摆满了各种不用的旧物品，在杂货室的一角摆放着一个兵器架。]],["id"]=[[fb17_85]],["item1"]=[[fb17item28]],["left"]=[[fb17_84]],["name"]=[[杂货室]],["permission"]=2,["right"]=[[fb17_86]],["stepMusic"]=[[jiaobu]]},["fb17_86"]={["dsc"]=[[这是一条长廊，上面画着江南秀美的工笔画。绿色的柱子朱红色的琉璃瓦，使得你不由得对江南艺术工匠的创造惊叹不已。丫鬟、家丁们走来走去，都忙着自己的事情，西面是杂货室，北面是长廊的延伸。]],["id"]=[[fb17_86]],["left"]=[[fb17_85]],["name"]=[[长廊]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb17_81]]},["fb17_87"]={["dsc"]=[[这里是紫萝山庄的藏书阁，天下武功皆荟粹与此，包罗万象，可与“镜花坞”的藏书相匹敌。屋子四周全是一排排高大的书架。]],["id"]=[[fb17_87]],["item1"]=[[fb17item16]],["item2"]=[[fb17item17]],["item3"]=[[fb17item23]],["name"]=[[藏书阁]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb17_88"]={["dsc"]=[[这就是举世闻名的燕氏皇族的还赐水阁，这里据说有很多武林人士向往以久的武功。只见墙上有一个书架子，上面摆满了各种武籍。]],["id"]=[[fb17_88]],["item1"]=[[fb17item27]],["item2"]=[[fb